import re
def slug_key(text):
    return re.sub(r'[^a-z0-9]+', '-', text.lower()).strip('-')

def strip_comment(text):
    for i, c in enumerate(text):
        if c == '#' and (i == 0 or text[i-1] != chr(92)):
            return text[:i].rstrip()
    return text.rstrip()

